/**
 * Test flow for deleteAttachment action
 * Demonstrates deleting an attachment
 */

import { action, Flow, wfa, trigger } from '@servicenow/sdk/automation'

export const testDeleteAttachment = Flow(
    {
        $id: Now.ID['test_delete_attachment_flow'],
        name: 'Test Delete Attachment',
        description: 'Tests the deleteAttachment core action',
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['test_delete_attachment_trigger'] },
        {
            table: 'incident',
            condition: 'active=true',
            run_flow_in: 'background',
        }
    ),
    (_params) => {
        wfa.action(
            action.core.deleteAttachment,
            { $id: Now.ID['test_delete_attachment_action'] },
            {
                table: 'incident',
                record: wfa.dataPill(_params.trigger.current.sys_id, 'reference'),
                attachment_file_name: 'test.pdf',
                delete_all_: false,
            }
        )

        wfa.action(
            action.core.log,
            { $id: Now.ID['test_delete_attachment_log'] },
            {
                log_level: 'info',
                log_message: `deleteAttachment outputs: record=${wfa.dataPill(_params.trigger.current.sys_id, 'reference')}`,
            }
        )
    }
)
